package interactive

import (
	"github.com/lanceman/zqk/pkg/objects"
)

// AutoGeneratedFieldsFilter filters out fields that should be auto-generated
// for CREATE operations (not UPDATE operations)
// Uses lifecycle objects to determine initial state and excludes system-generated fields
// System-generated fields are derived from specs (spec-driven, cached)
type AutoGeneratedFieldsFilter struct {
	lifecycleLoader   *objects.LifecycleLoader
	systemFieldsCache *objects.SystemFieldsRegistry // Cached system fields derived from specs
}

// NewAutoGeneratedFieldsFilter creates a new filter for create operations
func NewAutoGeneratedFieldsFilter(lifecycleLoader *objects.LifecycleLoader) *AutoGeneratedFieldsFilter {
	return &AutoGeneratedFieldsFilter{
		lifecycleLoader:   lifecycleLoader,
		systemFieldsCache: objects.GetGlobalSystemFieldsRegistry(),
	}
}

// FilterFieldsForCreate filters out auto-generated fields from a template
// Returns a new template with only fields that should be elicited from the user
func (f *AutoGeneratedFieldsFilter) FilterFieldsForCreate(
	kind string,
	templateWithTokens *TemplateWithTokens,
) (*TemplateWithTokens, error) {
	// Determine which fields should be excluded
	excludedFields := f.getAutoGeneratedFields(kind, templateWithTokens)

	// Build filtered template
	filteredFieldInfo := make(map[string]*FieldTokenInfo)
	filteredRequiredFields := []string{}
	filteredTokens := []string{}

	// Filter required fields
	for _, fieldName := range templateWithTokens.RequiredFields {
		if !excludedFields[fieldName] {
			filteredRequiredFields = append(filteredRequiredFields, fieldName)
			filteredFieldInfo[fieldName] = templateWithTokens.FieldInfo[fieldName]
			filteredTokens = append(filteredTokens, fieldName)
		}
	}

	// Filter optional fields (tokens)
	for _, token := range templateWithTokens.Tokens {
		if !excludedFields[token] {
			if _, exists := filteredFieldInfo[token]; !exists {
				if fieldInfo, ok := templateWithTokens.FieldInfo[token]; ok {
					filteredFieldInfo[token] = fieldInfo
					filteredTokens = append(filteredTokens, token)
				}
			}
		}
	}

	// Generate filtered template string (simplified - just track filtered fields)
	// In practice, we'd regenerate the template string, but for now we track filtered fields

	return &TemplateWithTokens{
		Template:       templateWithTokens.Template, // Original template (tokens still present)
		Tokens:         filteredTokens,
		FieldInfo:      filteredFieldInfo,
		RequiredFields: filteredRequiredFields,
	}, nil
}

// getAutoGeneratedFields returns a set of field names that should be excluded
// for CREATE operations
func (f *AutoGeneratedFieldsFilter) getAutoGeneratedFields(
	kind string,
	templateWithTokens *TemplateWithTokens,
) map[string]bool {
	excluded := make(map[string]bool)

	// System fields (derived from specs, cached)
	if f.systemFieldsCache != nil {
		systemFields, err := f.systemFieldsCache.GetSystemGeneratedFields()
		if err == nil {
			for fieldName := range systemFields {
				excluded[fieldName] = true
			}
		}
		// If error loading, fall through (graceful degradation)
	}

	// Status field - use origin status from lifecycle
	if f.lifecycleLoader != nil {
		if _, err := f.lifecycleLoader.GetOriginStatus(kind); err == nil {
			// Status field should not be elicited - use initial status
			excluded[objects.FieldKeyStatus] = true
		}
	}

	// Fields with defaults that should be auto-applied
	// Check field definitions for default values
	for fieldName, fieldInfo := range templateWithTokens.FieldInfo {
		if f.shouldExcludeFieldWithDefault(fieldName, fieldInfo) {
			excluded[fieldName] = true
		}
	}

	return excluded
}

// shouldExcludeFieldWithDefault determines if a field with a default should be excluded
// For CREATE operations, fields with defaults that indicate auto-generation should be excluded
func (f *AutoGeneratedFieldsFilter) shouldExcludeFieldWithDefault(
	fieldName string,
	_ *FieldTokenInfo,
) bool {
	// Fields that commonly have auto-generated defaults
	// These are typically set by the system, not the user

	// Archive fields (set when archived, not on create)
	if fieldName == "archived_at" || fieldName == "archived_by" {
		return true
	}

	// Change log (append-only, system-maintained)
	if fieldName == "change_log" {
		return true
	}

	// Status history (system-maintained)
	if fieldName == "status_history" {
		return true
	}

	// ID - can be auto-generated if not provided
	// However, users might want to specify IDs, so we keep it for now
	// (can be filtered out if desired)

	// Namespace ID - auto-generated from ID if not set
	// But user might want to specify, so we keep it

	// For now, we only exclude fields with explicit auto-generation semantics
	// Additional fields can be added based on spec analysis

	return false
}

// IsFieldAutoGenerated checks if a specific field should be auto-generated for CREATE operations
// Uses spec-driven system fields cache (derived from base_object and auditable specs)
func (f *AutoGeneratedFieldsFilter) IsFieldAutoGenerated(kind, fieldName string) bool {
	// Check if field is system-generated (derived from specs, cached)
	if f.systemFieldsCache != nil {
		if isSystem, err := f.systemFieldsCache.IsSystemGeneratedField(fieldName); err == nil && isSystem {
			return true
		}
		// If error loading, fall through to lifecycle check (graceful degradation)
	}

	// Status field - use origin status from lifecycle
	if fieldName == "status" {
		if f.lifecycleLoader != nil {
			if _, err := f.lifecycleLoader.GetOriginStatus(kind); err == nil {
				return true
			}
		}
	}

	// ID is auto-generated by InstanceBuilder if omitted
	if fieldName == "id" {
		return true
	}

	return false
}
